/**
 * **RULING 92 — fix the generator, never the artifact.**
 * (Adopted 2026-08-22, the author's ruling, NJ Hunt 6.)
 *
 * A generated artifact is never hand-corrected. The generator is fixed and the
 * artifact is regenerated. Hand-editing an output produces a file that **looks
 * fixed until it regenerates**, which is a silent class: nothing goes red, and
 * the defect returns on a schedule nobody is watching.
 *
 * ## The two instances this guard was built over
 *
 * 1. **The screenshot caption.** NJ Hunt 4 corrected it in `docs/state.md` — the
 *    generated file — and left the string in the script that writes it
 *    untouched. The script kept producing the wrong caption and the defect
 *    recurred one session later, in NJ Hunt 5.
 *
 * 2. **`data/hunt/nj-morris-municipal-sites.json`, which was worse.** Its
 *    generator had ALREADY been fixed; nobody had regenerated. The committed
 *    artifact pointed five municipalities at the wrong government's website —
 *    `morris_township` at Morris Plains', `chatham_township` at Chatham
 *    Borough's — and omitted six more. Every downstream hunt read it as current.
 *    Regenerating corrected all five and added the six.
 *
 * ## What this guard can and cannot see
 *
 * A generator that fetches from the network cannot be re-run inside a test: its
 * output legitimately changes when a government changes its website, and a test
 * that demanded byte-equality would fail on the world moving rather than on a
 * defect. So the guard is in two halves, and the first half is the one that
 * scales:
 *
 * - **Every generated artifact DECLARES its generator**, and is registered
 *   here. A file that says it is generated and names no command is a file
 *   nobody can regenerate — which is how a hand-edit becomes permanent.
 * - **Pure generators are re-run and diffed.** A generator whose inputs are all
 *   committed is deterministic, so its artifact must be byte-identical to what
 *   it produces right now.
 */
import test from "node:test";
import assert from "node:assert/strict";
import { execSync } from "node:child_process";
import { existsSync, readFileSync, writeFileSync } from "node:fs";
import { join } from "node:path";

import {
  DIGEST_FILE,
  GENERATED,
  type DigestFile,
} from "../lib/ops/generated-register.ts";
import { checkArtifact } from "../lib/ops/generator-digest.ts";

const ROOT = process.cwd();


test("RULING 92: every registered generated artifact exists and names its generator", () => {
  for (const a of GENERATED) {
    assert.ok(existsSync(join(ROOT, a.path)), `${a.path} is registered as generated but is absent`);
    assert.ok(
      a.command.trim().length > 0,
      `${a.path} names no command — a file nobody can regenerate is a file a hand-edit becomes permanent in`,
    );
    if (!a.pure) {
      assert.ok(
        (a.impurity ?? "").length > 20,
        `${a.path} is marked impure with no reason. Why it cannot be re-run is the finding, not a shrug.`,
      );
    }
  }
});

test("RULING 92: a file declaring itself GENERATED is registered here", () => {
  /*
   * `git ls-files` rather than a directory walk: it is the tracked set, and it
   * does not skip a hidden path the way ripgrep does. `-z` keeps names with
   * spaces whole.
   */
  const tracked = execSync("git ls-files -z", { cwd: ROOT, encoding: "utf8", maxBuffer: 64 * 1024 * 1024 })
    .split("\0")
    .filter((f) => /\.(?:ts|mts|tsx|md|json|jsonl|csv)$/.test(f));

  const registered = new Set(GENERATED.map((a) => a.path));
  const declaring: string[] = [];
  for (const file of tracked) {
    if (registered.has(file)) continue;
    let head: string;
    try {
      head = readFileSync(join(ROOT, file), "utf8").slice(0, 1200);
    } catch {
      continue;
    }
    // The exact phrasing this project uses in a generated file's own header.
    if (/GENERATED by `?(?:corepack )?pnpm /.test(head)) declaring.push(file);
  }
  assert.deepEqual(
    declaring,
    [],
    "these files declare themselves generated and are not in the register above — " +
      "add them, so a hand-edit to one is visible as a diff against its generator",
  );
});

/**
 * **A MISMATCH IS RE-RUN BEFORE IT IS BELIEVED, AND A RACE IS SAID OUT LOUD.**
 * (Repaired 2026-09-01, after this case failed three times under full-suite
 * load and passed every time in isolation.)
 *
 * ## Why this test in particular is raceable
 *
 * It is the only test in the suite that MUTATES THE WORKING TREE on purpose:
 * it runs each pure generator, compares the output to the committed bytes, and
 * restores the file in a `finally`. Meanwhile the rest of the suite runs
 * CONCURRENTLY — `node --test` parallelises across files — and several other
 * tests read the very artifacts this one is rewriting, notably the fourteen
 * governance views.
 *
 * Measured three times on 2026-09-01, at three different commits, all under a
 * full `pnpm gates` run, and each time it passed when re-run alone:
 *
 * ```
 *   UNKNOWN errno -4094 opening docs/governance/index.json   (Windows sharing violation)
 *   UNKNOWN errno -4094 opening docs/governance/history.md
 *   ASSERTION_FAILURE   a byte difference that did not reproduce
 * ```
 *
 * ## Why a re-run rather than a retry-until-green
 *
 * `lib/ops/flake-quarantine.ts` already states this repository's doctrine for
 * exactly this situation: *a check cannot be classified from one run; the
 * evidence that separates a flake from a regression is fails, then passes,
 * with nothing changed.* So the mismatch is re-derived ONCE.
 *
 * **A real defect reproduces.** A generator whose output genuinely drifted from
 * its artifact produces the same difference every time, and the second attempt
 * fails identically — which is still an assertion failure, with the same
 * message it always had.
 *
 * **A race does not reproduce**, and it is reported as its own outcome rather
 * than as either a pass or a byte difference. That distinction is the whole
 * point: a test that quietly retried until green would hide a real drift, and
 * a test that reported the race as a byte difference sends a session hunting a
 * defect that is not there. This one had already sent this session hunting
 * twice.
 *
 * It does NOT swallow the failure. A non-reproducing mismatch throws, naming
 * the concurrency explicitly, so the run still goes red and a human still
 * reads it — it just reads the truth.
 */
test("RULING 92: a PURE generator's artifact is byte-identical to what it produces now", () => {
  for (const a of GENERATED.filter((x) => x.pure)) {
    const full = join(ROOT, a.path);
    const committed = readFileSync(full, "utf8");
    try {
      execSync(a.command, { cwd: ROOT, stdio: "pipe", encoding: "utf8" });
      const regenerated = readFileSync(full, "utf8");
      if (regenerated === committed) continue;

      /* Re-derive once, from the committed bytes, before believing it. */
      writeFileSync(full, committed, "utf8");
      execSync(a.command, { cwd: ROOT, stdio: "pipe", encoding: "utf8" });
      const second = readFileSync(full, "utf8");

      if (second === committed) {
        throw new Error(
          `${a.path} differed from \`${a.command}\` on the first derivation and ` +
            "matched on the second, with nothing changed in between. That is a " +
            "CONCURRENCY OBSERVATION, not a byte difference: this is the only test " +
            "that rewrites the working tree, and the rest of the suite reads these " +
            "same artifacts while it runs. It is reported rather than retried away " +
            "because a test that retried until green would hide a real drift — and " +
            "it is not passed off as a generator defect, because that is what sent " +
            "two sessions hunting something that was not there.",
        );
      }

      assert.equal(
        second,
        committed,
        `${a.path} differs from what \`${a.command}\` produces, and the difference ` +
          "REPRODUCED on a second derivation — so it is real, not a race. " +
          "RULING 92: fix the GENERATOR and regenerate — never hand-correct the artifact.",
      );
    } finally {
      // Never leave the tree changed by a test, whatever the outcome.
      writeFileSync(full, committed, "utf8");
    }
  }
});

/* ========================================================================== */
/* RULING 102 — a generator fix is incomplete until its output is regenerated */
/* ========================================================================== */

/**
 * RULING 92 has no end. `data/hunt/nj-morris-municipal-sites.json` pointed
 * five municipalities at the wrong government's website **with its generator
 * already fixed** — somebody had done the RULING 92 thing, correctly, and
 * stopped. Nothing went red, because "fix the generator" was satisfied the
 * moment the generator was fixed.
 *
 * The completion condition: each generator's SOURCE CLOSURE is digested into
 * `tests/generator-digests.json`, and a generator whose digest has moved fails
 * here until its artifact is regenerated and `pnpm regen --write` records the
 * new digest.
 *
 * The digest is over the GENERATOR, not the artifact, and that is the whole
 * design. An artifact hash tells you the artifact changed; it cannot tell you
 * the artifact SHOULD have changed. A network generator's output legitimately
 * moves when a government moves its website — the generator's source moves
 * only when somebody edits it, which is exactly the event after which a re-run
 * is owed.
 */

test("RULING 102: every registered artifact records its generator's digest", () => {
  const full = join(ROOT, DIGEST_FILE);
  assert.ok(existsSync(full), `${DIGEST_FILE} is missing — run \`pnpm regen --write\``);
  const recorded = JSON.parse(readFileSync(full, "utf8")) as DigestFile;

  const missing = GENERATED.filter((a) => recorded[a.path] === undefined).map((a) => a.path);
  assert.deepEqual(
    missing,
    [],
    "these artifacts have no recorded generator digest, so nothing can tell whether their " +
      "generator has been fixed since they were written. Run `pnpm regen --write`.",
  );
});

test("RULING 102: no generator has moved since its artifact was last regenerated", () => {
  const recorded = JSON.parse(readFileSync(join(ROOT, DIGEST_FILE), "utf8")) as DigestFile;
  const stale: string[] = [];
  const unresolvable: string[] = [];
  for (const a of GENERATED) {
    const check = checkArtifact(ROOT, a, recorded[a.path]?.digest ?? null);
    if (check.verdict === "STALE" || check.verdict === "UNRECORDED") stale.push(a.path);
    if (check.verdict === "UNRESOLVABLE") unresolvable.push(`${a.path} — ${a.command}`);
  }
  assert.deepEqual(
    unresolvable,
    [],
    "these commands do not resolve to a repo file, so no completion condition can be " +
      "computed for them. A generator with no completion condition is the state RULING 102 ends.",
  );
  assert.deepEqual(
    stale,
    [],
    "the generator behind each of these has changed since the artifact was last " +
      "regenerated. RULING 102: regenerate the artifact, diff it, then `pnpm regen --write`. " +
      "Recording the digest WITHOUT regenerating makes this guard agree with a stale file.",
  );
});

test("RULING 102: the digest is sensitive to a change anywhere in the closure", () => {
  /*
   * Proof the instrument works, rather than a claim that it does. The closure
   * is the entry script PLUS every repo-local module it imports, transitively
   * — so a fix landing in `lib/hunt/wikipedia.ts` moves the digest of every
   * generator downstream of it, which is correct: those artifacts are owed a
   * re-run whether or not anyone remembered they existed.
   */
  const recorded = JSON.parse(readFileSync(join(ROOT, DIGEST_FILE), "utf8")) as DigestFile;
  for (const a of GENERATED) {
    const rec = recorded[a.path];
    assert.ok(rec, a.path);
    assert.ok(rec.files >= 1, `${a.path}: the source closure collapsed to ${rec.files} file(s)`);
    assert.match(rec.digest, /^[0-9a-f]{64}$/, `${a.path}: not a sha256`);
    assert.match(rec.regeneratedOn, /^\d{4}-\d{2}-\d{2}$/, `${a.path}: no regeneration date`);
  }
});

test("RULING 92 + RULING 107: no PURE generator reads the clock", () => {
  /*
   * **The class, closed rather than the two instances fixed.**
   *
   * 2 of the 7 PURE generators called `today()`, so their artifacts moved every
   * day on their own and the byte-identity test above could only pass on the
   * day somebody last ran them. It failed the first time a date rolled over
   * mid-session, which is how the class was found — and fixing only the
   * generator that happened to fail would have left the other standing.
   *
   * Two defects, one line of code each:
   *
   *   1. A "pure" generator whose output changes without its inputs changing is
   *      not pure, and a byte-identity test over it fails for the wrong reason
   *      and gets ignored.
   *   2. RULING 107 — a RUN stamp printed over committed data claims a currency
   *      the data does not have. `build-nj-rosters.mts` had the sharper form:
   *      `collectedAt: page?.walkedAt ?? AS_OF`, a FRESHNESS field falling back
   *      to the clock.
   *
   * The fix is `lib/ops/source-stamp.ts`, which carries the stamp from the
   * newest commit across the generator's committed inputs. This guard is what
   * stops a third appearing.
   *
   * IMPURE generators are untouched: one that fetches is genuinely a run, its
   * artifact legitimately moves, and it is registered with a reason.
   */
  const pkg = JSON.parse(readFileSync(join(ROOT, "package.json"), "utf8")) as {
    scripts: Record<string, string>;
  };
  const CLOCK = /\btoday\(\)|\bnew Date\(\)|\bDate\.now\(\)/;

  const offenders: string[] = [];
  let pureChecked = 0;
  let unresolved = 0;

  for (const a of GENERATED.filter((x) => x.pure)) {
    const name = /pnpm ([a-z:0-9-]+)/i.exec(a.command)?.[1];
    const target = name ? pkg.scripts[name] : undefined;
    const file = target ? /scripts\/[A-Za-z0-9._-]+\.m?[tj]s/.exec(target)?.[0] : undefined;
    if (!file) {
      // A generator this test cannot locate is reported, never counted as
      // clean — a sweep that quietly skips what it cannot reach is one
      // reporting green about nothing.
      unresolved += 1;
      continue;
    }
    pureChecked += 1;
    const src = readFileSync(join(ROOT, file), "utf8")
      .replace(/\/\*[\s\S]*?\*\//g, " ")
      .replace(/^\s*\/\/.*$/gm, " ");
    if (CLOCK.test(src)) offenders.push(`${a.path} <- ${file}`);
  }

  assert.equal(
    unresolved,
    0,
    `${unresolved} PURE generator(s) could not be located from their command — this sweep did ` +
      "not look at them, and that is a fact about the sweep",
  );
  assert.ok(pureChecked >= 5, `expected the sweep to reach the pure set, saw ${pureChecked}`);
  assert.deepEqual(
    offenders,
    [],
    "a PURE generator reads the clock, so its artifact cannot be reproducible and its date " +
      "claims a currency its committed inputs do not have. Carry the stamp with " +
      "`carriedSourceStamp` from lib/ops/source-stamp.ts, or register the generator as impure " +
      "with a reason.",
  );
});
